package com.aistock.notification.alert;
import static com.aistock.notification.alert.AlertRecords.*;import com.aistock.common.BusinessException;import com.fasterxml.jackson.databind.*;import java.math.BigDecimal;import java.time.*;import java.sql.*;import java.util.*;import java.security.MessageDigest;import java.nio.charset.StandardCharsets;import org.springframework.http.HttpStatus;
public final class AlertRuleService {
 public interface Boundaries {Boundary get(String instrument);}
 private final AlertRuleRepository repo;private final Boundaries boundaries;private final Clock clock;private final int limit;private final boolean evaluationEnabled;private final ObjectMapper mapper=new ObjectMapper().findAndRegisterModules().disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 public AlertRuleService(AlertRuleRepository repo,Boundaries boundaries,Clock clock,int limit){this(repo,boundaries,clock,limit,false);}
 public AlertRuleService(AlertRuleRepository repo,Boundaries boundaries,Clock clock,int limit,boolean evaluationEnabled){this.evaluationEnabled=evaluationEnabled;if(limit<1||limit>10000)throw new IllegalArgumentException("invalid alert limit");this.repo=repo;this.boundaries=boundaries;this.clock=clock;this.limit=limit;}
 public Rule create(UUID owner,Create input){if(input==null||input.requestId()==null||input.instrumentId()==null||!input.instrumentId().matches("(SH|SZ)[0-9]{6}"))throw invalid();var threshold=threshold(input.condition(),input.threshold());var hash=digest(input.instrumentId()+"|"+input.condition()+"|"+input.threshold());var old=replay(owner,input.requestId(),hash);if(old!=null)return old;var boundary=boundary(input.instrumentId());return repo.locked(owner,()->{var saved=replay(owner,input.requestId(),hash);if(saved!=null)return saved;if(repo.jdbc().queryForObject("select count(*) from alert_rule where user_id=?",Long.class,owner.toString())>=limit)throw conflict("ALERT_LIMIT_REACHED");fresh(boundary);var now=clock.instant();var rule=new Rule(UUID.randomUUID(),input.instrumentId(),input.condition(),threshold,true,0,boundary.effectiveAfterTradeDate(),boundary.rawVersionId(),now,now,availability());repo.jdbc().update("insert into alert_rule(rule_id,user_id,instrument_id,condition_code,threshold_value,enabled,revision,effective_after_date,boundary_raw_version,boundary_json,created_at,updated_at) values(?,?,?,?,?,true,0,?,?,?,?,?)",rule.id().toString(),owner.toString(),rule.instrumentId(),rule.condition(),new BigDecimal(threshold),rule.effectiveAfterTradeDate(),rule.boundaryRawVersionId().toString(),json(boundary),Timestamp.from(now),Timestamp.from(now));repo.jdbc().update("insert into alert_rule_request(user_id,request_id,request_hash,response_json,created_at) values(?,?,?,?,?)",owner.toString(),input.requestId().toString(),hash,json(rule),Timestamp.from(now));return rule;});}
 public Rule patch(UUID owner,UUID id,Patch input){if(input==null||input.revision()==null||input.revision()<0||(input.condition()==null&&input.threshold()==null&&input.enabled()==null))throw invalid();var initial=find(owner,id);if(initial.revision()!=input.revision())throw conflict("ALERT_REVISION_CONFLICT");String condition=input.condition()==null?initial.condition():input.condition();String value=threshold(condition,input.threshold()==null?initial.threshold():input.threshold());boolean enabled=input.enabled()==null?initial.enabled():input.enabled();boolean change=!condition.equals(initial.condition())||new BigDecimal(value).compareTo(new BigDecimal(initial.threshold()))!=0;var boundary=(change||enabled&&!initial.enabled())?boundary(initial.instrumentId()):null;return repo.locked(owner,()->{var old=find(owner,id);if(old.revision()!=input.revision())throw conflict("ALERT_REVISION_CONFLICT");if(boundary!=null)fresh(boundary);long revision=old.revision()+1;var date=boundary==null?old.effectiveAfterTradeDate():boundary.effectiveAfterTradeDate();var version=boundary==null?old.boundaryRawVersionId():boundary.rawVersionId();var now=clock.instant();repo.jdbc().update("update alert_rule set condition_code=?,threshold_value=?,enabled=?,revision=?,effective_after_date=?,boundary_raw_version=?,boundary_json=coalesce(?,boundary_json),updated_at=? where rule_id=? and user_id=?",condition,new BigDecimal(value),enabled,revision,date,version.toString(),boundary==null?null:json(boundary),Timestamp.from(now),id.toString(),owner.toString());return find(owner,id);});}
 public Page list(UUID owner,int page,int size){
  if(page<1||page>100000||size<1||size>50)throw invalid();
  var total=repo.jdbc().queryForObject("select count(*) from alert_rule where user_id=?",Long.class,owner.toString());
  var checks=new LinkedHashMap<UUID,Check>();
  var items=repo.jdbc().query("""
   select r.*, e.state as check_state, coalesce(e.finished_at,e.created_at) as check_time,
          coalesce(e.checked_trade_date,t.trade_date) as check_date
   from (select * from alert_rule where user_id=? order by created_at desc,rule_id limit ? offset ?) r
   left join alert_evaluation_operation e on e.operation_id=(
     select candidate.operation_id from alert_evaluation_operation candidate
     where candidate.owner_id=r.user_id and candidate.rule_id=r.rule_id and candidate.rule_revision=r.revision
     order by candidate.created_at desc,candidate.operation_id desc limit 1
   )
   left join alert_trigger t on t.trigger_id=e.trigger_id and t.owner_id=r.user_id and t.rule_id=r.rule_id
   order by r.created_at desc,r.rule_id
   """,(rs,n)->{
    var rule=row(rs);
    var checkedAt=rs.getTimestamp("check_time");
    var date=rs.getDate("check_date");
    if(checkedAt!=null)checks.put(rule.id(),new Check(rs.getString("check_state"),checkedAt.toInstant(),date==null?null:date.toLocalDate()));
    return rule;
   },owner.toString(),size,(long)(page-1)*size);
  return new Page(items,page,size,total,Map.copyOf(checks));
 }
 private Rule find(UUID owner,UUID id){var rows=repo.jdbc().query("select * from alert_rule where rule_id=? and user_id=?",(rs,n)->row(rs),id.toString(),owner.toString());if(rows.isEmpty())throw new BusinessException("RESOURCE_NOT_FOUND","规则不存在",HttpStatus.NOT_FOUND);return rows.get(0);}
 private Rule row(ResultSet rs)throws SQLException{return new Rule(UUID.fromString(rs.getString("rule_id")),rs.getString("instrument_id"),rs.getString("condition_code"),rs.getBigDecimal("threshold_value").stripTrailingZeros().toPlainString(),rs.getBoolean("enabled"),rs.getLong("revision"),rs.getDate("effective_after_date").toLocalDate(),UUID.fromString(rs.getString("boundary_raw_version")),rs.getTimestamp("created_at").toInstant(),rs.getTimestamp("updated_at").toInstant(),availability());}
 private Rule replay(UUID owner,UUID request,String hash){var rows=repo.jdbc().queryForList("select request_hash,response_json from alert_rule_request where user_id=? and request_id=?",owner.toString(),request.toString());if(rows.isEmpty())return null;if(!hash.equals(rows.get(0).get("request_hash")))throw conflict("ALERT_REQUEST_CONFLICT");try{var r=mapper.readValue((String)rows.get(0).get("response_json"),Rule.class);return new Rule(r.id(),r.instrumentId(),r.condition(),r.threshold(),r.enabled(),r.revision(),r.effectiveAfterTradeDate(),r.boundaryRawVersionId(),r.createdAt(),r.updatedAt(),availability());}catch(Exception e){throw new BusinessException("ALERT_RECORD_INVALID","规则记录暂不可读",HttpStatus.INTERNAL_SERVER_ERROR);}}
 private String availability(){return evaluationEnabled?"ENABLED":"NOT_ENABLED";}
 private Boundary boundary(String instrument){try{var b=boundaries.get(instrument);if(b==null||!instrument.equals(b.instrumentId())||!"baostock".equals(b.provider())||!"alert-boundary-v1".equals(b.definition())||b.rawVersionId()==null||b.asOf()==null||b.calendarHash()==null||!b.calendarHash().matches("[a-f0-9]{64}")||b.latestPublishedTradeDate()==null||b.expectedCompletedTradeDate()==null||b.effectiveAfterTradeDate()==null||!b.effectiveAfterTradeDate().equals(b.latestPublishedTradeDate().isAfter(b.expectedCompletedTradeDate())?b.latestPublishedTradeDate():b.expectedCompletedTradeDate())||b.effectiveAfterTradeDate().isAfter(LocalDate.now(clock.withZone(ZoneId.of("Asia/Shanghai")))))throw invalid();fresh(b);return b;}catch(Exception e){org.slf4j.LoggerFactory.getLogger(AlertRuleService.class).warn("Alert boundary unavailable: type={}",e.getClass().getSimpleName());throw new BusinessException("ALERT_BOUNDARY_UNAVAILABLE","预警生效日期暂无法核验，请稍后重试；停用规则仍可操作",HttpStatus.SERVICE_UNAVAILABLE);}}
 private void fresh(Boundary b){if(b.asOf().isBefore(clock.instant().minusSeconds(15))||b.asOf().isAfter(clock.instant().plusSeconds(5)))throw new BusinessException("ALERT_BOUNDARY_UNAVAILABLE","预警边界已过期，请重试",HttpStatus.SERVICE_UNAVAILABLE);}
 static String threshold(String condition,String raw){if(condition==null||!Set.of("PRICE_ABOVE","PRICE_BELOW","DAILY_RISE","DAILY_FALL").contains(condition)||raw==null||!raw.matches("[0-9]{1,14}(\\.[0-9]{1,6})?"))throw invalid();var n=new BigDecimal(raw);boolean price=condition.startsWith("PRICE_");if(n.signum()<=0||(!price&&(n.scale()>4||n.compareTo(new BigDecimal("100"))>0)))throw invalid();return n.stripTrailingZeros().toPlainString();}
 static BusinessException invalid(){return new BusinessException("VALIDATION_FAILED","预警参数无效，请检查条件、正数阈值及小数位",HttpStatus.BAD_REQUEST);}
 static BusinessException conflict(String code){return new BusinessException(code,"规则已变化、请求冲突或达到当前数量上限，请刷新后重试",HttpStatus.CONFLICT);}
 private String json(Object o){try{return mapper.writeValueAsString(o);}catch(Exception e){throw new IllegalStateException("alert encoding failed");}}
 private String digest(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException("digest unavailable");}}
}
